DO $$
DECLARE
  v_prayer_id uuid;
  v_sec_entrada uuid;
  v_sec_eucar uuid;
  v_sec_comunhao uuid;
  v_sec_final uuid;
BEGIN
  SELECT id INTO v_prayer_id FROM public.prayers WHERE slug='missa-ordinario';
  IF v_prayer_id IS NULL THEN RAISE NOTICE 'missa-ordinario não encontrado'; RETURN; END IF;
  SELECT id INTO v_sec_entrada FROM public.prayer_sections WHERE prayer_id=v_prayer_id AND slug='entrada';
  SELECT id INTO v_sec_eucar FROM public.prayer_sections WHERE prayer_id=v_prayer_id AND slug='eucaristica';
  SELECT id INTO v_sec_comunhao FROM public.prayer_sections WHERE prayer_id=v_prayer_id AND slug='comunhao';
  SELECT id INTO v_sec_final FROM public.prayer_sections WHERE prayer_id=v_prayer_id AND slug='final';

  -- Ato Penitencial: tag Formas A/B/C
  UPDATE public.prayer_blocks SET meta=coalesce(meta,'{}'::jsonb)||jsonb_build_object('option_group','penitential-act','option_key','A','option_label','Forma A · Confiteor') WHERE section_id=v_sec_entrada AND order_index=2;
  UPDATE public.prayer_blocks SET meta=coalesce(meta,'{}'::jsonb)||jsonb_build_object('option_group','penitential-act','option_key','B','option_label','Forma B') WHERE section_id=v_sec_entrada AND order_index=3;
  UPDATE public.prayer_blocks SET meta=coalesce(meta,'{}'::jsonb)||jsonb_build_object('option_group','penitential-act','option_key','C','option_label','Forma C · Kyrie tropado') WHERE section_id=v_sec_entrada AND order_index=4;

  -- Rito da Paz
  UPDATE public.prayer_blocks SET meta=coalesce(meta,'{}'::jsonb)||jsonb_build_object('option_group','pax','option_key','padrao','option_label','Fórmula habitual') WHERE section_id=v_sec_comunhao AND order_index=2;

  -- Reformula "Oração Eucarística — Consagração" como EP II
  UPDATE public.prayer_blocks
  SET title='Oração Eucarística II',
      content=jsonb_build_object(
        'text', E'Na verdade, ó Pai, vós sois santo e fonte de toda santidade. Santificai, pois, estas oferendas, derramando sobre elas o vosso Espírito, a fim de que se tornem para nós o Corpo e † o Sangue de Jesus Cristo, vosso Filho e Senhor nosso.\n\nEstando para ser entregue e abraçando livremente a paixão, ele tomou o pão, deu graças e o partiu e deu a seus discípulos, dizendo:\n\nTOMAI, TODOS, E COMEI: ISTO É O MEU CORPO, QUE SERÁ ENTREGUE POR VÓS.\n\nDo mesmo modo, ao fim da ceia, ele tomou o cálice em suas mãos, deu graças novamente e o deu a seus discípulos, dizendo:\n\nTOMAI, TODOS, E BEBEI: ESTE É O CÁLICE DO MEU SANGUE, O SANGUE DA NOVA E ETERNA ALIANÇA, QUE SERÁ DERRAMADO POR VÓS E POR TODOS PARA REMISSÃO DOS PECADOS. FAZEI ISTO EM MEMÓRIA DE MIM.\n\nEis o mistério da fé!\n— Anunciamos, Senhor, a vossa morte e proclamamos a vossa ressurreição. Vinde, Senhor Jesus!\n\nCelebrando, pois, a memória da morte e ressurreição do vosso Filho, nós vos oferecemos, ó Pai, o pão da vida e o cálice da salvação; e vos agradecemos porque nos tornastes dignos de estar aqui na vossa presença e vos servir. E nós vos suplicamos que, participando do Corpo e Sangue de Cristo, sejamos reunidos pelo Espírito Santo num só corpo.\n\nLembrai-vos, ó Pai, da vossa Igreja que se faz presente pelo mundo inteiro; que ela cresça na caridade, com o Papa N., com o nosso Bispo N. e todos os ministros do vosso povo.\n\nLembrai-vos também dos nossos irmãos e irmãs que morreram na esperança da ressurreição e de todos os que partiram desta vida: acolhei-os junto a vós na luz da vossa face. Enfim, nós vos pedimos, tende piedade de todos nós e dai-nos participar da vida eterna, com a Virgem Maria, Mãe de Deus, com São José, seu esposo, os bem-aventurados Apóstolos e todos os que neste mundo vos serviram, a fim de vos louvarmos e glorificarmos por Jesus Cristo, vosso Filho.',
        'rubric','O sacerdote profere as palavras da consagração com voz clara e reverente. Todos se ajoelham nesse momento se possível.'),
      meta=coalesce(meta,'{}'::jsonb)||jsonb_build_object('option_group','eucharistic-prayer','option_key','ep2','option_label','II · Comum')
  WHERE section_id=v_sec_eucar AND order_index=6;

  -- EP I (Cânon Romano)
  INSERT INTO public.prayer_blocks (prayer_id, section_id, type, title, content, order_index, meta) VALUES
  (v_prayer_id, v_sec_eucar, 'prayer', 'Oração Eucarística I (Cânon Romano)',
   jsonb_build_object(
     'text', E'Pai de misericórdia, a quem sobem nossos louvores, nós vos pedimos por Jesus Cristo, vosso Filho e Senhor nosso, que aceiteis e abençoeis † estes dons, † estas oferendas, este sacrifício puro e santo, que vos oferecemos, antes de tudo, pela vossa Igreja santa e católica: concedei-lhe paz e proteção, unidade e governo em toda a terra, em comunhão com o vosso servo o Papa N., com o nosso Bispo N. e todos os que guardam a fé católica, recebida dos Apóstolos.\n\nLembrai-vos, ó Pai, dos vossos filhos e filhas N. e N. e de todos os que circundam este altar: vós conheceis a sua fé e o seu desvelo; por eles e por todos os seus e por todos aqueles que lhes são caros, nós vos oferecemos, e também eles vos oferecem este sacrifício de louvor, por si e por todos os seus, pela redenção de suas almas, pela esperança da salvação e da incolumidade; e vos consagram os seus votos, a vós, eterno Deus, vivo e verdadeiro.\n\nEm comunhão com toda a Igreja, veneramos a memória, em primeiro lugar, da gloriosa sempre Virgem Maria, Mãe de nosso Deus e Senhor Jesus Cristo, de São José, seu esposo, dos vossos Apóstolos e Mártires: Pedro e Paulo, André, e de todos os vossos Santos. Por seus méritos e preces, concedei-nos sempre a vossa proteção.\n\nRecebei, ó Pai, com bondade, esta oferenda de nós, vossos servos, e de toda a vossa família: dai-nos sempre a vossa paz, livrai-nos da condenação eterna e acolhei-nos entre os vossos eleitos.\n\nDignai-vos, ó Pai, aceitar e santificar estas oferendas, a fim de que se tornem para nós o Corpo e † o Sangue de vosso amado Filho, Jesus Cristo, nosso Senhor.\n\nNa véspera de sua paixão, ele tomou o pão em suas santas e veneráveis mãos, elevou os olhos ao céu, a vós, ó Pai onipotente, deu graças, bendisse e partiu o pão e o deu a seus discípulos, dizendo:\n\nTOMAI, TODOS, E COMEI: ISTO É O MEU CORPO, QUE SERÁ ENTREGUE POR VÓS.\n\nDo mesmo modo, ao fim da ceia, ele tomou este precioso cálice em suas santas e veneráveis mãos, deu graças novamente e o deu a seus discípulos, dizendo:\n\nTOMAI, TODOS, E BEBEI: ESTE É O CÁLICE DO MEU SANGUE, O SANGUE DA NOVA E ETERNA ALIANÇA, QUE SERÁ DERRAMADO POR VÓS E POR TODOS PARA REMISSÃO DOS PECADOS. FAZEI ISTO EM MEMÓRIA DE MIM.\n\nEis o mistério da fé!\n— Salvador do mundo, salvai-nos, vós que nos libertastes pela cruz e ressurreição.\n\nCelebrando, pois, a memória da bendita paixão do vosso Filho, da sua ressurreição dentre os mortos e gloriosa ascensão aos céus, nós, vossos servos, e também vosso povo santo, vos oferecemos, ó Pai, dentre os bens que nos destes, o sacrifício puro, santo e imaculado, Pão santo da vida eterna e Cálice da perpétua salvação.\n\nRecebei-o, ó Pai, com face serena e favorável, como recebestes as ofertas do vosso justo servo Abel, o sacrifício do nosso patriarca Abraão e a oblação puríssima do vosso sumo sacerdote Melquisedec.\n\nSuplicamo-vos, Deus onipotente, que, por vosso santo Anjo, mandeis levar esta oferenda ao vosso altar celestial diante da vossa divina Majestade, a fim de que, ao participarmos deste altar, recebendo o santíssimo Corpo e Sangue de vosso Filho, sejamos repletos de toda graça e bênção do céu.\n\nLembrai-vos, também, ó Pai, dos vossos filhos e filhas N. e N., que partiram desta vida marcados com o sinal da fé, e dormem o sono da paz. A eles, Senhor, e a todos os que descansam em Cristo, dai a felicidade, a luz e a paz.\n\nE a todos nós pecadores, que confiamos na vossa imensa misericórdia, concedei, não por nossos méritos, mas por vossa bondade, o convívio dos Apóstolos e Mártires: João Batista e Estêvão, Matias e Barnabé, e de todos os vossos Santos. Por Cristo, nosso Senhor.\n\nPor ele não cessais de criar todos estes bens e os santificais, vivificais, abençoais e distribuís entre nós.',
     'rubric','Também chamado Cânon Romano. Reservado às solenidades e domingos, especialmente do Tempo Comum e dos Apóstolos.'),
   61, jsonb_build_object('option_group','eucharistic-prayer','option_key','ep1','option_label','I · Cânon Romano')),

  (v_prayer_id, v_sec_eucar, 'prayer', 'Oração Eucarística III',
   jsonb_build_object(
     'text', E'Na verdade, vós sois santo, ó Deus do universo, e tudo o que criastes proclama o vosso louvor, porque, por Jesus Cristo, vosso Filho e Senhor nosso, e pela força do Espírito Santo, dais vida e santidade a todas as coisas e não cessais de reunir o vosso povo, para que vos ofereça em toda parte, do nascer ao pôr do sol, um sacrifício perfeito.\n\nPor isso, nós vos suplicamos: santificai pelo Espírito Santo as oferendas que vos apresentamos para serem consagradas, a fim de que se tornem o Corpo e † o Sangue de Jesus Cristo, vosso Filho e Senhor nosso, que nos mandou celebrar este mistério.\n\nNa noite em que ia ser entregue, ele tomou o pão, deu graças e o partiu e deu a seus discípulos, dizendo:\n\nTOMAI, TODOS, E COMEI: ISTO É O MEU CORPO, QUE SERÁ ENTREGUE POR VÓS.\n\nDo mesmo modo, ao fim da ceia, ele tomou o cálice em suas mãos, deu graças novamente e o deu a seus discípulos, dizendo:\n\nTOMAI, TODOS, E BEBEI: ESTE É O CÁLICE DO MEU SANGUE, O SANGUE DA NOVA E ETERNA ALIANÇA, QUE SERÁ DERRAMADO POR VÓS E POR TODOS PARA REMISSÃO DOS PECADOS. FAZEI ISTO EM MEMÓRIA DE MIM.\n\nEis o mistério da fé!\n— Todas as vezes que comemos deste pão e bebemos deste cálice, anunciamos, Senhor, a vossa morte, enquanto esperamos a vossa vinda!\n\nCelebrando agora, ó Pai, a memória do vosso Filho, da sua paixão que nos salva, da sua gloriosa ressurreição e da sua ascensão ao céu, e esperando a sua nova vinda, nós vos oferecemos em ação de graças este sacrifício de vida e santidade.\n\nOlhai com bondade a oferenda da vossa Igreja, reconhecei o sacrifício que nos reconcilia convosco e concedei que, alimentando-nos com o Corpo e o Sangue do vosso Filho, sejamos repletos do Espírito Santo e nos tornemos em Cristo um só corpo e um só espírito.\n\nQue ele faça de nós uma oferenda perfeita para alcançarmos a vida eterna com os vossos santos: a Virgem Maria, Mãe de Deus, São José, seu esposo, os vossos bem-aventurados Apóstolos e gloriosos Mártires e todos os Santos, nossos intercessores junto a vós.\n\nPor este sacrifício de reconciliação, dai, ó Pai, paz e salvação ao mundo inteiro. Confirmai na fé e na caridade a vossa Igreja, enquanto caminha neste mundo: o vosso servo o Papa N., o nosso Bispo N., com os Bispos do mundo inteiro, o clero e todo o povo que conquistastes.\n\nAtendei às preces da vossa família, que está aqui, na vossa presença. Reuni em vós, Pai de misericórdia, todos os vossos filhos e filhas dispersos pelo mundo inteiro.\n\nAcolhei com bondade no vosso reino os nossos irmãos e irmãs que partiram desta vida e todos os que morreram na vossa amizade. Unidos a eles, esperamos também nós saciar-nos eternamente da vossa glória, por Cristo, Senhor nosso, pelo qual dais ao mundo todo bem e toda graça.'),
   62, jsonb_build_object('option_group','eucharistic-prayer','option_key','ep3','option_label','III · Domingos e festas')),

  (v_prayer_id, v_sec_eucar, 'prayer', 'Oração Eucarística IV',
   jsonb_build_object(
     'text', E'Nós vos damos graças, Pai santo, pela vossa presença ativa na história dos homens. Enviastes vosso Filho, nascido de Maria Virgem, semelhante a nós em tudo, exceto no pecado; a nós, pobres e pecadores, entregastes o vosso Filho amado. Vede, ó Pai, o sacrifício que vós mesmos destes à vossa Igreja, e concedei, pelo poder do Espírito, que, ao participarmos do Corpo e Sangue de Cristo, sejamos, no mesmo Cristo, um só corpo e um só espírito.\n\nQue o Espírito Santo faça de nós uma oferenda permanente a vós agradável, para que possamos obter o reino prometido, com os vossos eleitos: com a Virgem Maria, Mãe de Deus, com São José, seu esposo, com os vossos Apóstolos e Mártires, e todos os Santos.\n\nNa noite em que ia ser entregue, ele tomou o pão em suas mãos, deu graças, partiu e o deu a seus discípulos, dizendo:\n\nTOMAI, TODOS, E COMEI: ISTO É O MEU CORPO, QUE SERÁ ENTREGUE POR VÓS.\n\nDo mesmo modo, tomou o cálice, deu graças novamente e o deu a seus discípulos, dizendo:\n\nTOMAI, TODOS, E BEBEI: ESTE É O CÁLICE DO MEU SANGUE, O SANGUE DA NOVA E ETERNA ALIANÇA, QUE SERÁ DERRAMADO POR VÓS E POR TODOS PARA REMISSÃO DOS PECADOS. FAZEI ISTO EM MEMÓRIA DE MIM.\n\nEis o mistério da fé!\n— Cada vez que comemos deste pão e bebemos deste cálice, anunciamos, Senhor, a vossa morte, enquanto esperamos a vossa vinda!\n\nE agora, ó Pai, celebrando o memorial da nossa redenção, anunciamos a morte de Cristo e sua descida entre os mortos, proclamamos a sua ressurreição e ascensão à vossa direita, e esperando a sua vinda gloriosa, nós vos oferecemos o seu Corpo e Sangue, sacrifício que a vós agrada e ao mundo salva. Olhai com bondade, ó Pai, esta oferenda que vós mesmos destes à vossa Igreja.\n\nConcedei aos vossos filhos e filhas, a quem chamastes a participar deste mesmo sacrifício, que, alimentando-se do Corpo e Sangue de vosso Filho, se congreguem em um só corpo pela força do Espírito Santo e formem em Cristo uma oferta viva e agradável a vós, para louvor da vossa glória.\n\nE agora, ó Pai, lembrai-vos de todos aqueles pelos quais vos oferecemos esta oblação: em primeiro lugar, do vosso servo o Papa N., do nosso Bispo N. e do colégio dos Bispos, de todo o clero, dos que oferecem este sacrifício, dos aqui reunidos, de todo o vosso povo, dos que vos procuram de coração sincero.\n\nLembrai-vos, ó Pai, dos nossos irmãos e irmãs que morreram na paz de Cristo, e de todos os falecidos cuja fé só a vós é conhecida.\n\nPai de bondade, concedei a todos nós, filhos e filhas de Deus, a herança do céu, em companhia da bem-aventurada Virgem Maria, Mãe de Deus, com São José, seu esposo, com os Apóstolos e todos os Santos, no vosso reino. E ali, com toda a criação livre da corrupção do pecado e da morte, vos glorificaremos por Cristo, Senhor nosso, por quem dais ao mundo todo bem.'),
   63, jsonb_build_object('option_group','eucharistic-prayer','option_key','ep4','option_label','IV · Anafórica')),

  (v_prayer_id, v_sec_eucar, 'prayer', 'Oração Eucarística da Reconciliação I',
   jsonb_build_object(
     'text', E'Nós vos louvamos, ó Pai, sempre e em toda parte, por Jesus Cristo, vosso amado Filho, presente entre nós no mistério da reconciliação. Vede, ó Pai, com quanto amor os homens se voltam para vós: eis o vosso povo, congregado pelo Espírito Santo, unido no Corpo de Cristo.\n\nSantificai, ó Pai, estes dons pela efusão do vosso Espírito, para que se tornem o Corpo e † o Sangue do vosso Filho Jesus Cristo, que nos mandou celebrar este mistério, sinal da aliança eterna que fizestes conosco em seu Sangue.\n\nEle, na hora em que se entregava para nos salvar, tomou o pão em suas mãos, deu graças e o partiu, e o deu a seus discípulos, dizendo:\n\nTOMAI, TODOS, E COMEI: ISTO É O MEU CORPO, QUE SERÁ ENTREGUE POR VÓS.\n\nDo mesmo modo, ao fim da ceia, ele tomou o cálice do vinho, deu graças novamente e o deu a seus discípulos, dizendo:\n\nTOMAI, TODOS, E BEBEI: ESTE É O CÁLICE DO MEU SANGUE, O SANGUE DA NOVA E ETERNA ALIANÇA, QUE SERÁ DERRAMADO POR VÓS E POR TODOS PARA REMISSÃO DOS PECADOS. FAZEI ISTO EM MEMÓRIA DE MIM.\n\nEis o mistério da fé!\n— Anunciamos, Senhor, a vossa morte e proclamamos a vossa ressurreição. Vinde, Senhor Jesus!\n\nCelebrando, ó Pai santo, a reconciliação que nos ofereceis em Cristo, nós vos suplicamos: pela comunhão no Corpo e no Sangue do vosso Filho, dai-nos o vosso Espírito, para que possamos superar toda divisão e discórdia, e nos tornar sinal de unidade e instrumento de vossa paz. Lembrai-vos do vosso Papa N., do nosso Bispo N. e de todos os que servem à vossa Igreja.\n\nAcolhei, ó Pai, todos os vossos filhos e filhas, vivos e defuntos, e conduzi-nos, com a Virgem Maria e todos os santos, à casa do vosso reino, onde poderemos, para sempre, cantar o vosso louvor.'),
   64, jsonb_build_object('option_group','eucharistic-prayer','option_key','rec1','option_label','Reconciliação I')),

  (v_prayer_id, v_sec_eucar, 'prayer', 'Oração Eucarística da Reconciliação II',
   jsonb_build_object(
     'text', E'Nós vos damos graças, Pai santo, pois nos convidastes ao vosso banquete de vida. Vosso Filho Jesus reuniu ao redor de si o vosso povo, que o Espírito Santo faz crescer na unidade e na paz.\n\nSantificai, ó Pai, com o mesmo Espírito, estas oferendas: sobre elas realizai a consagração pela força da vossa palavra e pelo poder do Espírito, para que se tornem para nós o Corpo e † o Sangue de Jesus, vosso Filho, que nos reuniu no mesmo memorial.\n\nEle mesmo, tendo sido entregue à sua paixão, tomou o pão, deu graças, o partiu e o deu a seus discípulos, dizendo:\n\nTOMAI, TODOS, E COMEI: ISTO É O MEU CORPO, QUE SERÁ ENTREGUE POR VÓS.\n\nDo mesmo modo, tomando o cálice, ele deu graças de novo e o deu a seus discípulos, dizendo:\n\nTOMAI, TODOS, E BEBEI: ESTE É O CÁLICE DO MEU SANGUE, O SANGUE DA NOVA E ETERNA ALIANÇA, QUE SERÁ DERRAMADO POR VÓS E POR TODOS PARA REMISSÃO DOS PECADOS. FAZEI ISTO EM MEMÓRIA DE MIM.\n\nEis o mistério da fé!\n— Todas as vezes que comemos deste pão e bebemos deste cálice, anunciamos, Senhor, a vossa morte, enquanto esperamos a vossa vinda!\n\nCelebrando, ó Pai santo, o memorial de Jesus Cristo, nosso Salvador, que, por sua paixão e morte na cruz, fizestes entrar na glória da ressurreição e assentar à vossa direita, nós anunciamos a obra do vosso amor até que ele venha, e vos oferecemos o pão da vida e o cálice da bênção.\n\nConcedei que este sacrifício, entregue à vossa Igreja para servir à unidade dos crentes, contribua para a paz e concórdia do mundo inteiro. Lembrai-vos do vosso Papa N., do nosso Bispo N. e de todo o clero.\n\nEnfim, quando chegar o dia em que, livres da corrupção do pecado e da morte, seremos admitidos com toda a criação libertada à mesa do vosso reino, damos, desde já, graças a vós, por Jesus Cristo, vosso Filho.'),
   65, jsonb_build_object('option_group','eucharistic-prayer','option_key','rec2','option_label','Reconciliação II')),

  (v_prayer_id, v_sec_eucar, 'prayer', 'Oração Eucarística para Diversas Necessidades',
   jsonb_build_object(
     'text', E'Nós vos damos graças, ó Pai, e proclamamos a vossa grandeza, pois em tudo mostrastes a vossa bondade. Enviastes vosso Filho Jesus Cristo, que se fez em tudo semelhante a nós, exceto no pecado, para amar aqueles que amais.\n\nReconhecemos, com admiração, a obra do vosso Espírito, sempre presente na vida do vosso povo, guiando-o pelos caminhos do tempo até a alegria plena do vosso reino. Por isso, ó Pai, humildemente vos suplicamos: santificai pelo mesmo Espírito estas oferendas, para que se tornem o Corpo e † o Sangue de Jesus Cristo, vosso Filho e Senhor nosso, que nos mandou celebrar este mistério.\n\nNa noite em que ia ser entregue, ele tomou o pão, deu graças e o partiu, e o deu a seus discípulos, dizendo:\n\nTOMAI, TODOS, E COMEI: ISTO É O MEU CORPO, QUE SERÁ ENTREGUE POR VÓS.\n\nDo mesmo modo, tomou o cálice, deu graças novamente e o deu a seus discípulos, dizendo:\n\nTOMAI, TODOS, E BEBEI: ESTE É O CÁLICE DO MEU SANGUE, O SANGUE DA NOVA E ETERNA ALIANÇA, QUE SERÁ DERRAMADO POR VÓS E POR TODOS PARA REMISSÃO DOS PECADOS. FAZEI ISTO EM MEMÓRIA DE MIM.\n\nEis o mistério da fé!\n— Salvador do mundo, salvai-nos, vós que nos libertastes pela cruz e ressurreição.\n\nCelebrando, ó Pai santo, o memorial de Cristo, vosso Filho, nosso Salvador, que pela paixão e morte na cruz fizestes entrar na glória da ressurreição e colocastes à vossa direita, anunciamos a obra do vosso amor até que ele venha e vos oferecemos o pão da vida e o cálice da bênção.\n\nOlhai com bondade a oferenda da vossa Igreja, que vos apresenta o sacrifício de Cristo. Concedei-nos, pela comunhão com o Corpo e Sangue de vosso Filho, tornar-nos em Cristo um só corpo e um só espírito.\n\nQue ele faça de nós uma oferenda perene, cuja plena realização esperamos alcançar em vossa companhia, com a Virgem Maria, Mãe de Deus, com São José, seu esposo, com os Apóstolos e todos os santos.\n\nConfortai, com a força deste Sacramento, a vossa Igreja, unida em torno do vosso servo o Papa N. e do nosso Bispo N.; e a todos os fiéis que aqui vos servem, e a todo o vosso povo, e a todos aqueles que vos buscam com sinceridade.\n\nLembrai-vos também dos nossos irmãos e irmãs falecidos, cuja fé só a vós é conhecida: admiti-os, em vossa bondade, na luz da vossa face; e a nós todos, um dia, no vosso reino, onde, unidos com toda a criação, vos daremos glória, por Cristo, Senhor nosso.'),
   66, jsonb_build_object('option_group','eucharistic-prayer','option_key','div','option_label','Diversas Necessidades'));

  -- Despedida
  UPDATE public.prayer_blocks
  SET content=jsonb_build_object('text',E'Ide em paz, e o Senhor vos acompanhe.\n— Graças a Deus.', 'rubric','Fórmula habitual (Ite, missa est).'),
      meta=coalesce(meta,'{}'::jsonb)||jsonb_build_object('option_group','dismissal','option_key','padrao','option_label','Ide em paz')
